package org.apache.commons.lang.time;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang.time.StopWatch#stop()
 */
public class StopWatch_stop_TriageGen5Test {

    @Test
    public void testStop_WhenRunning_ShouldStopSuccessfully() {
        StopWatch stopWatch = new StopWatch();
        stopWatch.start();

        stopWatch.stop();

        // Verify state change via toString or behavior
        // Since runningState is private, we verify by ensuring no exception is thrown 
        // and the state is consistent with a stopped watch.
        Assert.assertTrue(stopWatch.toString().contains("stopped"));
    }

    @Test
    public void testStop_WhenSuspended_ShouldStopSuccessfully() {
        StopWatch stopWatch = new StopWatch();
        stopWatch.start();
        stopWatch.suspend();

        stopWatch.stop();

        Assert.assertTrue(stopWatch.toString().contains("stopped"));
    }

    @Test(expected = IllegalStateException.class)
    public void testStop_WhenNotStarted_ShouldThrowIllegalStateException() {
        StopWatch stopWatch = new StopWatch();
        // State is STATE_STOPPED or initial state
        stopWatch.stop();
    }

    @Test(expected = IllegalStateException.class)
    public void testStop_WhenAlreadyStopped_ShouldThrowIllegalStateException() {
        StopWatch stopWatch = new StopWatch();
        stopWatch.start();
        stopWatch.stop();

        // Second attempt to stop should throw exception because state is now STATE_STOPPED
        stopWatch.stop();
    }

    @Test
    public void testStop_UpdatesStopTime() throws InterruptedException {
        StopWatch stopWatch = new StopWatch();
        stopWatch.start();
        Thread.sleep(10); // Ensure some time passes
        stopWatch.stop();

        long timeAtStop = stopWatch.getTime();
        Assert.assertTrue("Time should be greater than 0", timeAtStop > 0);
    }
}
